def art_lookup(node, key_bytes, depth=0):
    while node is not None:
        if node.is_leaf:
            return node.value if node.key == key_bytes else None
        # Path compression: verify inline compressed prefix
        plen = node.prefix_len
        if plen > 0:
            end = min(depth + plen, len(key_bytes))
            if key_bytes[depth:depth + min(plen, 8)] != node.prefix[:min(plen, 8)]:
                return None
            depth += plen
        if depth >= len(key_bytes):
            return None
        node = node.find_child(key_bytes[depth])  # Node4/16/48/256
        depth += 1
    return None
